BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('00000000-0000-4000-a102-000000000001','automation@example.test',now());
INSERT INTO businesses(id,owner_id,name,business_type,slug,billing_mode,partner_plan) VALUES('10000000-0000-4000-a102-000000000001','00000000-0000-4000-a102-000000000001','Automation Business','general','review-102','comped','chat_only');
INSERT INTO contacts(id,business_id,name,email,source_channel) VALUES('20000000-0000-4000-a102-000000000001','10000000-0000-4000-a102-000000000001','Customer','automatedcustomer@example.test','manual');
SELECT review_initialize_settings('10000000-0000-4000-a102-000000000001','00000000-0000-4000-a102-000000000001');
SELECT ok(NOT (SELECT automation_enabled FROM review_settings WHERE business_id='10000000-0000-4000-a102-000000000001'),'completion automation defaults off');
UPDATE review_email_control SET enabled=true,pilot_business_ids=ARRAY['10000000-0000-4000-a102-000000000001'::uuid];
INSERT INTO customer_service_events(id,business_id,contact_id,description,status,completed_at,idempotency_key,request_fingerprint) VALUES
 ('70000000-0000-4000-a102-000000000001','10000000-0000-4000-a102-000000000001','20000000-0000-4000-a102-000000000001','Old job','completed',now(),'fixture-old','test-fingerprint-old'),
 ('70000000-0000-4000-a102-000000000002','10000000-0000-4000-a102-000000000001','20000000-0000-4000-a102-000000000001','Future job','open',NULL,'fixture-future','test-fingerprint-future');
SELECT review_configure_automation('10000000-0000-4000-a102-000000000001','00000000-0000-4000-a102-000000000001',true,'email');
SELECT is((SELECT count(*)::integer FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),0,'enabling automation does not replay old jobs');
UPDATE customer_service_events SET status='completed',completed_at=now() WHERE id='70000000-0000-4000-a102-000000000002';
SELECT is((SELECT count(*)::integer FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),0,'completion without recorded channel permission cannot enroll');
SELECT review_record_permission('10000000-0000-4000-a102-000000000001','00000000-0000-4000-a102-000000000001','20000000-0000-4000-a102-000000000001','email',true,'Customer agreed to email review requests in person','America/Chicago');
INSERT INTO customer_service_events(id,business_id,contact_id,description,status,completed_at,idempotency_key,request_fingerprint) VALUES('70000000-0000-4000-a102-000000000003','10000000-0000-4000-a102-000000000001','20000000-0000-4000-a102-000000000001','New completed job','completed',now(),'fixture-new','test-fingerprint-new');
SELECT is((SELECT count(*)::integer FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),1,'new completion with durable permission creates one source event');
SELECT is((SELECT extract(hour FROM scheduled_at AT TIME ZONE 'America/Chicago')::integer FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),10,'default delivery is10AM recipient timezone');
SELECT is((SELECT (scheduled_at AT TIME ZONE 'America/Chicago')::date FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),(now() AT TIME ZONE 'America/Chicago')::date+1,'default delivery is next local day');
UPDATE customer_service_events SET status='open',completed_at=NULL WHERE id='70000000-0000-4000-a102-000000000003';
SELECT is((SELECT status FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),'cancelled','reopening cancels the source event');
UPDATE customer_service_events SET status='completed',completed_at=now() WHERE id='70000000-0000-4000-a102-000000000003';
SELECT is((SELECT count(*)::integer FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),1,'recompletion cannot mint another source event');
SELECT is((SELECT status FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),'cancelled','recompletion does not resurrect cancelled automation');
-- A temporarily paused, fresh source waits without losing its original time.
UPDATE review_automation_events SET status='pending',scheduled_at=now()-interval '2 minutes' WHERE business_id='10000000-0000-4000-a102-000000000001';
UPDATE review_settings SET paused=true WHERE business_id='10000000-0000-4000-a102-000000000001';
SELECT is((SELECT count(*)::integer FROM review_claim_automations() WHERE business_id='10000000-0000-4000-a102-000000000001'),0,'business pause leaves fresh automation unclaimed');
SELECT is((SELECT status FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),'pending','temporary pause does not permanently block a completed job');
UPDATE review_settings SET paused=false WHERE business_id='10000000-0000-4000-a102-000000000001';
UPDATE businesses SET billing_mode='stripe',partner_plan=NULL WHERE id='10000000-0000-4000-a102-000000000001';
SELECT is((SELECT count(*)::integer FROM review_claim_automations() WHERE business_id='10000000-0000-4000-a102-000000000001'),0,'unpaid automation stays queued');
UPDATE businesses SET billing_mode='comped',partner_plan='chat_only' WHERE id='10000000-0000-4000-a102-000000000001';
SELECT is((SELECT count(*)::integer FROM review_claim_automations() WHERE business_id='10000000-0000-4000-a102-000000000001'),1,'restored payment resumes a fresh delayed source');
SELECT is((SELECT scheduled_at FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),now()-interval '2 minutes','resume retains the original schedule and stale deadline');
UPDATE review_automation_events SET status='pending',scheduled_at=now()-interval '25 hours' WHERE business_id='10000000-0000-4000-a102-000000000001';
SELECT is((SELECT count(*)::integer FROM review_claim_automations() WHERE business_id='10000000-0000-4000-a102-000000000001'),0,'automation more than 24 hours late is not claimed');
SELECT is((SELECT status FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),'expired','stale automation expires instead of creating a burst after recovery');
SELECT review_record_permission('10000000-0000-4000-a102-000000000001','00000000-0000-4000-a102-000000000001','20000000-0000-4000-a102-000000000001','email',false,'Owner revoked email review permission',NULL);
SELECT ok((SELECT revoked_at IS NOT NULL FROM review_permissions WHERE business_id='10000000-0000-4000-a102-000000000001'),'explicit owner permission revocation is durable');
SELECT is(review_contact_destination(jsonb_populate_record(NULL::contacts,'{"source_channel":"web_chat","phone_number":"+15745550101","provided_phone_number":"(574) 555-0102"}'),'sms'),'+15745550102','review SMS uses normalized widget callback number before primary routing phone');
SELECT is(review_contact_destination(jsonb_populate_record(NULL::contacts,'{"source_channel":"web_chat","phone_number":"session_unverified","provided_phone_number":"not a phone"}'),'sms'),NULL::text,'invalid callback and session identities never become SMS destinations');
UPDATE contacts SET phone_number='(574) 555-0103' WHERE id='20000000-0000-4000-a102-000000000001';
SELECT is(review_recipient_block('10000000-0000-4000-a102-000000000001','20000000-0000-4000-a102-000000000001','+15745550103',ARRAY['phone:+15745550103']),NULL::text,'normalized legacy phone passes the same recipient identity check as preview');
UPDATE businesses SET owner_id=NULL WHERE id='10000000-0000-4000-a102-000000000001';
SELECT is((SELECT count(*)::integer FROM review_automation_events WHERE business_id='10000000-0000-4000-a102-000000000001'),0,'business tombstone erases automation destination snapshots');
SELECT * FROM finish();ROLLBACK;
